import{_ as i,a0 as r,w as s,s as l,ao as u,I as a,x as n,a1 as p,A as o}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const f=JSON.parse('{"title":"如何在VirtualBox中的Linux客户機系統間共享磁盤 | LCTT x X-CMD","titleTemplate":false,"description":"如何在VirtualBox中的Linux客户機系統間共享磁盤 | LCTT (201406) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在VirtualBox中的Linux客户機系統間共享磁盤 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在VirtualBox中的Linux客户機系統間共享磁盤 | LCTT (201406) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201406/20140529 How To Share Disks In VirtualBox Between Linux Guest OS","title":"如何在VirtualBox中的Linux客户機系統間共享磁盤","tag":"201406","desc":""},"relativePath":"201406/20140529 How To Share Disks In VirtualBox Between Linux Guest OS.md","filePath":"[post].md"}'),x={name:"201406/20140529 How To Share Disks In VirtualBox Between Linux Guest OS.md"};function d(m,t,g,T,w,_){const e=r("Link");return s(),l("div",null,[t[11]||(t[11]=u('<h1 id="如何在virtualbox中的linux客户機系統間共享磁盤" tabindex="-1">如何在VirtualBox中的Linux客户機系統間共享磁盤 <a class="header-anchor" href="#如何在virtualbox中的linux客户機系統間共享磁盤" aria-label="Permalink to “如何在VirtualBox中的Linux客户機系統間共享磁盤”">​</a></h1><p>在本教程中，讓我來給你們展示一下如何在VirtualBox中的兩個Linux客户機系統間共享一個磁盤。</p><p>本教程對於那些想配置一下並玩玩GFS或者集羣的人來説還是很有幫助的。</p><p>下圖是VirtualBox的標準界面：</p><p><img src="http://180016988.r.cdn77.net/wp-content/uploads/2014/05/2014-05-28_102225.png" alt=""></p><p>第一個客户系統機CentOS1：</p><p><img src="http://180016988.r.cdn77.net/wp-content/uploads/2014/05/2014-05-28_102252.png" alt=""></p><p>第二個客户機系統CentOS2：</p><p><img src="http://180016988.r.cdn77.net/wp-content/uploads/2014/05/2014-05-28_102314.png" alt=""></p><p>給第一台機器添加額外的磁盤：</p><p><img src="http://180016988.r.cdn77.net/wp-content/uploads/2014/05/2014-05-28_102459.png" alt=""></p><p>點擊文件-&gt;虛擬介質管理器（Control+D）打開虛擬介質管理器界面：</p><p><img src="http://180016988.r.cdn77.net/wp-content/uploads/2014/05/2014-05-28_102657.png" alt=""></p><p>設置磁盤為可共享（Shareable）：</p><p><img src="http://180016988.r.cdn77.net/wp-content/uploads/2014/05/2014-05-28_102719.png" alt=""></p><p>在客户機CentOS 2上，你可以添加現有磁盤，該磁盤在CentOS1客户機系統之前已經創建好：</p><p><img src="http://180016988.r.cdn77.net/wp-content/uploads/2014/05/v2014-05-28_113908.png" alt=""></p><p>完成後，你可以重啓第二個客户機系統，並檢查驅動器是否已經添加：</p><p><img src="http://180016988.r.cdn77.net/wp-content/uploads/2014/05/2014-05-28_111903.png" alt=""></p><p>大功告成。</p><hr>',21)),a("p",null,[t[1]||(t[1]=n("via: ",-1)),p(e,{href:"http://www.unixmen.com/share-disks-virtualbox-linux-guest-os/"},{default:o(()=>[...t[0]||(t[0]=[n("http://www.unixmen.com/share-disks-virtualbox-linux-guest-os/",-1)])]),_:1})]),a("p",null,[t[4]||(t[4]=n("譯者：",-1)),p(e,{href:"https://github.com/GOLinux"},{default:o(()=>[...t[2]||(t[2]=[n("GOLinux",-1)])]),_:1}),t[5]||(t[5]=n(" 校對：",-1)),p(e,{href:"https://github.com/wxy"},{default:o(()=>[...t[3]||(t[3]=[n("wxy",-1)])]),_:1})]),a("p",null,[t[8]||(t[8]=n("本文由 ",-1)),p(e,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...t[6]||(t[6]=[n("LCTT",-1)])]),_:1}),t[9]||(t[9]=n(" 原創翻譯，",-1)),p(e,{href:"http://linux.cn/"},{default:o(()=>[...t[7]||(t[7]=[n("Linux中國",-1)])]),_:1}),t[10]||(t[10]=n(" 榮譽推出",-1))])])}const B=i(x,[["render",d]]);export{f as __pageData,B as default};
